quires": []}, {"group": "Modulbaukasten", "key": "modules.publish", "label": "Modulversionen veröffentlichen", "page": "builder", "roles": [], "requires": ["modules.edit"]}, {"group": "Modulbaukasten", "key": "modules.restore", "label": "Frühere Modulversion wiederherstellen", "page": "builder", "roles": [], "requires": ["modules.publish"]}, {"group": "Modulbaukasten", "key": "modules.records", "label": "Freigegebene Moduleinträge speichern", "page": "modules", "roles": ["employee", "studio_manager"], "requires": []}, {"group": "Startseite", "key": "home.create", "label": "Startseiteneinträge anlegen", "page": "dashboard", "roles": [], "requires": []}, {"group": "Startseite", "key": "home.edit", "label": "Startseiteneinträge bearbeiten", "page": "dashboard", "roles": [], "requires": []}, {"group": "Startseite", "key": "home.publish", "label": "Startseiteneinträge veröffentlichen", "page": "dashboard", "roles": [], "requires": []}, {"group": "Startseite", "key": "home.archive", "label": "Startseiteneinträge ausblenden", "page": "dashboard", "roles": [], "requires": []}, {"group": "Chat", "key": "chat.send", "label": "Nachrichten senden", "page": "chat", "roles": ["employee", "studio_manager"], "requires": []}, {"group": "Chat", "key": "chat.channels", "label": "Studioübergreifende Chatkanäle verwalten", "page": "chat", "roles": [], "requires": []}, {"group": "Feedback", "key": "feedback.submit", "label": "Eigenes Feedback abgeben und verfolgen", "page": "feedback", "roles": ["employee", "studio_manager"], "requires": []}, {"group": "Feedback", "key": "feedback.manage", "label": "Feedback des eigenen Studios bearbeiten", "page": "feedback", "roles": [], "requires": []}, {"group": "Feedback", "key": "feedback.reassign", "label": "Zuständigkeit einer Meldung ändern", "page": "feedback", "roles": [], "requires": ["feedback.manage"]}, {"group": "Feedback", "key": "feedback.routes", "label": "Feedback-Zuständigkeiten festlegen", "page": "feedback", "roles": [], "requires": []}, {"group": "Nutzerverwaltung", "key": "users.view", "label": "Mitarbeiterprofile ansehen", "page": "access", "roles": [], "requires": []}, {"group": "Nutzerverwaltung", "key": "users.invite", "label": "Einzelne Mitarbeiter einladen", "page": "access", "roles": [], "requires": ["users.view"]}, {"group": "Nutzerverwaltung", "key": "users.import", "label": "Mitarbeiter per CSV oder Excel importieren", "page": "access", "roles": [], "requires": ["users.invite"]}, {"group": "Nutzerverwaltung", "key": "users.profile", "label": "Berufliche Profilinformationen bearbeiten", "page": "access", "roles": [], "requires": ["users.view"]}, {"group": "Nutzerverwaltung", "key": "users.access", "label": "Zugänge sperren und Studiozuordnungen verwalten", "page": "access", "roles": [], "requires": ["users.view"]}, {"group": "Nutzerverwaltung", "key": "users.login", "label": "Anmeldelinks anfordern", "page": "access", "roles": [], "requires": ["users.view"]}, {"group": "Controlling", "key": "controlling.view", "label": "Controlling für eigene Studios ansehen", "page": "controlling", "roles": [], "requires": []}, {"group": "Controlling", "key": "controlling.export", "label": "Controlling als CSV exportieren", "page": "controlling", "roles": [], "requires": ["controlling.view"]}, {"group": "Aufgaben", "key": "tasks.private", "label": "Private Aufgaben für mich erstellen und bearbeiten", "page": "tasks", "roles": ["employee", "studio_manager"], "requires": [], "since": 10}, {"group": "Aufgaben", "key": "tasks.repeat", "label": "Wiederkehrende Aufgaben anlegen", "page": "tasks", "roles": ["employee", "studio_manager"], "requires": [], "since": 10}, {"group": "Kalender", "key": "calendar.create", "label": "Eigene Termine anlegen und bearbeiten", "page": "calendar", "roles": ["employee", "studio_manager"], "requires": [], "since": 10}, {"group": "Kalender", "key": "calendar.team", "label": "Termine für das Studio anlegen und bearbeiten", "page": "calendar", "roles": ["studio_manager"], "requires": ["calendar.create"], "since": 10}, {"group": "Gerätewartung", "key": "maintenance.manage", "label": "Gerätewartungen planen und bearbeiten", "page": "calendar", "roles": ["studio_manager"], "requires": ["tasks.create", "tasks.assign", "tasks.repeat"], "since": 10}, {"group": "Lernhub", "key": "learning.videos", "label": "Kursvideos aufnehmen, hochladen und zuordnen", "page": "learning", "roles": [], "requires": ["learning.courses"], "since": 11}, {"group": "Onboarding", "key": "onboarding.templates", "label": "Onboardingvorlagen erstellen und freigeben", "page": "learning", "roles": [], "requires": ["learning.courses"], "since": 12}, {"group": "Onboarding", "key": "onboarding.assign", "label": "Einarbeitungspläne Mitarbeitern zuweisen", "page": "learning", "roles": [], "requires": ["onboarding.review", "learning.assign", "tasks.create", "tasks.assign"], "since": 12}, {"group": "Onboarding", "key": "onboarding.review", "label": "Onboarding im eigenen Studio begleiten und bestätigen", "page": "learning", "roles": ["studio_manager"], "requires": [], "since": 12}, {"group": "KI-Assistent", "key": "assistant.ask", "label": "KI-Antworten zu freigegebenen Inhalten nutzen", "page": "knowledge", "roles": [], "requires": ["knowledge.read"], "since": 13}]'::jsonb) as c(key text,label text,page text,roles text[],requires text[]); $$;
create or replace function public.team_access_context()
returns jsonb language plpgsql stable security definer set search_path='' as $$ declare p public.profiles; a public.team_page_access; begin
 select * into p from public.profiles where id=auth.uid() and active;
 if not found then raise insufficient_privilege using message='Active employee required'; end if;
 select * into a from public.team_page_access where user_id=p.id;
 return jsonb_build_object('version',13,'pages',case when p.role='admin' then app_private.default_team_pages('admin') else coalesce(a.pages,app_private.default_team_pages(p.role)) end,'can_design',app_private.design_right('edit'),'capabilities',app_private.function_effective(p.id));
end; $$;
create or replace function public.admin_function_access(p_user uuid,p_grants text[] default null,p_revision integer default null)
returns jsonb language plpgsql security definer set search_path='' as $$ declare member public.profiles; previous public.team_function_access; extra text[]; before_count integer; needed_pages text[]; begin
 if not app_private.is_admin() then raise insufficient_privilege using message='Administrator required'; end if;
 select * into member from public.profiles where id=p_user for update;
 if not found then raise check_violation using message='Unknown employee'; end if;
 select * into previous from public.team_function_access where user_id=p_user;
 if p_grants is not null then
  if member.role='admin' then raise check_violation using message='Administrators retain full access'; end if;
  if previous.revision is distinct from p_revision then raise serialization_failure using message='Function permissions changed'; end if;
  if array_position(p_grants,null) is not null or cardinality(p_grants)>100 or exists(select 1 from unnest(p_grants) g where not exists(select 1 from app_private.function_catalog() c where c.key=g)) then raise check_violation using message='Invalid function permission'; end if;
  extra:=array(select distinct unnest(p_grants));
  loop
   before_count:=cardinality(extra);
   extra:=array(select distinct x from (select unnest(extra) x union select unnest(c.requires) from app_private.function_catalog() c where c.key=any(extra)) s);
   exit when cardinality(extra)=before_count;
  end loop;
  insert into public.team_function_access(user_id,grants,updated_by) values(p_user,extra,auth.uid()) on conflict(user_id) do update set grants=excluded.grants,revision=team_function_access.revision+1,updated_at=clock_timestamp(),updated_by=auth.uid();
  -- Keep old screens readable; the function-grant row is authoritative once present.
  insert into public.module_permissions(user_id,can_create,can_edit,can_publish) values(p_user,'modules.create'=any(extra),'modules.edit'=any(extra),'modules.publish'=any(extra)) on conflict(user_id) do update set can_create=excluded.can_create,can_edit=excluded.can_edit,can_publish=excluded.can_publish;
  select coalesce(array_agg(distinct c.page),'{}') into needed_pages from app_private.function_catalog() c where c.key=any(extra);
  if 'calendar'=any(needed_pages) then needed_pages:=needed_pages||array['tasks']; end if;
  if cardinality(needed_pages)>0 then
   insert into public.team_page_access(user_id,pages,updated_by) values(p_user,array(select distinct unnest(app_private.default_team_pages(member.role)||needed_pages)),auth.uid()) on conflict(user_id) do update set pages=array(select distinct unnest(team_page_access.pages||needed_pages)),revision=team_page_access.revision+1,updated_at=clock_timestamp(),updated_by=auth.uid();
  end if;
  insert into public.team_access_events(actor_id,target_id,event,details) values(auth.uid(),p_user,'function_permissions_updated',jsonb_build_object('grants',extra));
 end if;
 select * into previous from public.team_function_access where user_id=p_user;
 return jsonb_build_object('version',13,'grants',app_private.function_grants(p_user),'effective',app_private.function_effective(p_user),'role_defaults',(select coalesce(array_agg(c.key),'{}') from app_private.function_catalog() c where member.role='admin' or member.role=any(c.roles)),'revision',previous.revision,'role',member.role);
end; $$;

create table if not exists app_private.team_assistant_requests(
 id uuid primary key default gen_random_uuid(),
 user_id uuid not null references public.profiles(id) on delete cascade,
 created_at timestamptz not null default clock_timestamp()
);
create index if not exists team_assistant_requests_time on app_private.team_assistant_requests(created_at);
create index if not exists team_assistant_requests_user_time on app_private.team_assistant_requests(user_id,created_at);
alter table app_private.team_assistant_requests enable row level security;
revoke all on app_private.team_assistant_requests from public,anon,authenticated;

create or replace function public.team_assistant_status()
returns jsonb language plpgsql stable security definer set search_path='' as $$ begin
 if not (app_private.can_page('knowledge') and app_private.has_function('knowledge.read')) then raise insufficient_privilege using message='Knowledge access required'; end if;
 return jsonb_build_object('version',1,'can_ask',app_private.has_function('assistant.ask'));
end; $$;

create or replace function public.reserve_team_assistant_request()
returns jsonb language plpgsql volatile security definer set search_path='' as $$
declare instant timestamptz; day_start timestamptz; day_end timestamptz; last_request timestamptz;
begin
 if not (app_private.can_page('knowledge') and app_private.has_function('knowledge.read') and app_private.has_function('assistant.ask')) then raise insufficient_privilege using message='Assistant access required'; end if;
 -- Serialize across Edge Function instances, including concurrent requests by the same user.
 perform pg_advisory_xact_lock(hashtextextended('teamhub-assistant-budget',0));
 instant:=clock_timestamp();
 day_start:=date_trunc('day',instant at time zone 'Europe/Berlin') at time zone 'Europe/Berlin';
 day_end:=(date_trunc('day',instant at time zone 'Europe/Berlin')+interval '1 day') at time zone 'Europe/Berlin';
 delete from app_private.team_assistant_requests where created_at<instant-interval '7 days';
 select max(created_at) into last_request from app_private.team_assistant_requests where user_id=auth.uid();
 if last_request>instant-interval '10 seconds' then return jsonb_build_object('allowed',false,'retry_after',greatest(1,ceil(extract(epoch from last_request+interval '10 seconds'-instant))::integer)); end if;
 if (select count(*) from app_private.team_assistant_requests where user_id=auth.uid() and created_at>=day_start and created_at<day_end)>=50
 or (select count(*) from app_private.team_assistant_requests where created_at>=day_start and created_at<day_end)>=500 then
  return jsonb_build_object('allowed',false,'retry_after',greatest(1,ceil(extract(epoch from day_end-instant))::integer));
 end if;
 insert into app_private.team_assistant_requests(user_id,created_at) values(auth.uid(),instant);
 return jsonb_build_object('allowed',true,'retry_after',0);
end; $$;
revoke all on function public.team_assistant_status(),public.reserve_team_assistant_request() from public,anon;
grant execute on function public.team_assistant_status(),public.reserve_team_assistant_request() to authenticated;
commit;
